{
  "Comment": "Document processing workflow",
  "StartAt": "Textract",
  "States": {
    "Textract": {
      "Type": "Task",
      "Resource": "arn:aws:states:::aws-sdk:textract:startDocumentAnalysis",
      "Next": "RedactPII"
    },
    "RedactPII": {
      "Type": "Task",
      "Resource": "arn:aws:states:::sagemaker-runtime:invokeEndpoint",
      "Next": "StoreResults"
